import ipaddress

def plan_pod_range(range_cidr,node_prefix,current_node_cidrs,max_nodes,surge_nodes):
    network=ipaddress.ip_network(range_cidr,strict=True)
    if network.version!=4:raise ValueError("this planner currently accepts IPv4 secondary ranges only")
    if type(node_prefix) is not int or not network.prefixlen<=node_prefix<=32:raise ValueError("invalid per-node prefix")
    if type(max_nodes) is not int or type(surge_nodes) is not int or max_nodes<1 or surge_nodes<0:raise ValueError("invalid node capacity")
    block_size=1<<(32-node_prefix);total=1<<(node_prefix-network.prefixlen)
    allocated=[]
    for raw in current_node_cidrs:
        block=ipaddress.ip_network(raw,strict=True)
        if block.version!=4 or block.prefixlen!=node_prefix or not block.subnet_of(network):raise ValueError("allocated node CIDR outside range or wrong prefix")
        allocated.append(block)
    if len(set(allocated))!=len(allocated):raise ValueError("duplicate allocated node CIDR")
    free=total-len(allocated);required=max_nodes+surge_nodes;additional=max(0,required-len(allocated))
    return {"total_node_blocks":total,"allocated_node_blocks":len(allocated),"free_node_blocks":free,
        "peak_nodes_required":required,"additional_blocks_required":additional,"fits_peak":free>=additional,
        "pod_addresses_per_node_block":block_size,
        "action":"reserve enough Pod secondary-range blocks for max nodes plus upgrade surge; verify allocated node CIDRs, not only live Pod count" if free<additional else "verify actual node CIDR allocation during scale-up and upgrade surge"}
